import React, { useEffect, useState } from 'react';

function App() {
  const [logs, setLogs] = useState([]);

  // Fetch threat logs from backend
  const fetchLogs = async () => {
    try {
      const response = await fetch('http://localhost:5001/threat_logs');
      if (response.ok) {
        const data = await response.json();
        setLogs(data);
      } else {
        console.error('Failed to fetch threat logs');
      }
    } catch (error) {
      console.error('Error fetching threat logs:', error);
    }
  };

  useEffect(() => {
    fetchLogs();
    // Optionally, refresh logs every 5 seconds
    const interval = setInterval(fetchLogs, 5000);
    return () => clearInterval(interval);
  }, []);

  // Download logs as JSON file
  const downloadLogs = () => {
    const element = document.createElement('a');
    const file = new Blob([JSON.stringify(logs, null, 2)], { type: 'application/json' });
    element.href = URL.createObjectURL(file);
    element.download = 'threat_logs.json';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h2>Threat Log</h2>
      <div style={{ border: '1px solid #ccc', padding: '10px', height: '300px', overflowY: 'scroll', backgroundColor: '#f9f9f9' }}>
        {logs.length === 0 ? (
          <p>No logs available</p>
        ) : (
          logs.map(log => (
            <div key={log.id} style={{ marginBottom: '10px', paddingBottom: '5px', borderBottom: '1px solid #ddd' }}>
              <div><strong>Time:</strong> {log.timestamp}</div>
              <div><strong>Threat:</strong> {log.threat_name}</div>
              <div><strong>Location:</strong> {log.threat_location}</div>
              <div><strong>Message:</strong> {log.message}</div>
              <div><strong>Solution:</strong> {log.solution}</div>
            </div>
          ))
        )}
      </div>
      <button onClick={downloadLogs} style={{ marginTop: '10px', padding: '8px 16px', cursor: 'pointer' }}>
        Download Logs
      </button>
    </div>
  );
}

export default App;
